import { ref } from 'vue'

/**
 * A copy button's state: copy(text) writes the clipboard, and copied is true for 1.5s after. Where the Clipboard API is
 * refused (a browser or a frame that denies it), the older copy command still works inside the click. Only if both are
 * refused does it answer false, and the text stays selectable.
 */
export function useCopy(ms = 1500) {
  const copied = ref(false)
  let timer: ReturnType<typeof setTimeout> | undefined
  async function copy(text: string): Promise<boolean> {
    try {
      await navigator.clipboard.writeText(text)
    }
    catch {
      if (!copyByCommand(text)) return false
    }
    copied.value = true
    clearTimeout(timer)
    // ds-latency: the Copied label stays 1.5s after the copy, which has already happened.
    timer = setTimeout(() => { copied.value = false }, ms)
    return true
  }
  return { copied, copy }
}

// The older way: select the text in an unseen field, run the copy command, hand focus back.
function copyByCommand(text: string) {
  const back = document.activeElement as HTMLElement | null
  const field = document.createElement('textarea')
  field.value = text
  field.setAttribute('readonly', '')
  field.style.position = 'fixed'
  field.style.opacity = '0'
  document.body.appendChild(field)
  field.select()
  let ok = false
  try { ok = document.execCommand('copy') }
  catch { ok = false }
  field.remove()
  back?.focus()
  return ok
}

'use client'
import { useState } from 'react'
import { CodeCopy } from '@/react/components/ui/CodeCopy'
import { cn } from '@/react/lib/cn'

// Code to read and copy (the console's CodeWindow.vue), one dark window on the site and in the product: a pill for
// each request or language and Copy on one row, a rule, then the code in 12px Geist Mono. There is always a pill: one
// names the code (`label`, else cURL for a curl command, else Shell), several pick it (`samples`). Copy takes all of
// it. Code reads left to right in every language.
export interface CodeBlockProps {
  code?: string
  label?: string
  samples?: { label: string, code: string }[]
  onCopied?: () => void
  className?: string
}

export function CodeBlock({ code, label, samples, onCopied, className }: CodeBlockProps) {
  const [picked, setPicked] = useState(0)
  const tabs = samples?.map(s => s.label) ?? [label ?? (code?.startsWith('curl') ? 'cURL' : 'Shell')]
  const shown = samples?.[picked]?.code ?? code ?? ''
  return (
    <div data-ds="code-block" className={cn('bg-code text-code-fg', className)} dir="ltr">
      <div className="flex min-h-11 flex-wrap items-center justify-between gap-2 border-b border-[color-mix(in_srgb,var(--ds-color-off-white)_24%,transparent)] p-2">
        {tabs.length > 1
          ? (
              <div className="flex min-w-0 flex-wrap gap-0.5" role="tablist" aria-label={label ?? 'code'}>
                {tabs.map((t, i) => (
                  <button
                    key={t}
                    type="button"
                    role="tab"
                    aria-selected={picked === i}
                    className="inline-flex h-control-sm cursor-pointer items-center px-2.5 text-meta leading-5 font-medium text-code-muted transition-[color,background-color] duration-120 ease-standard hover:text-code-fg focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-surface-accent aria-selected:bg-code-raised aria-selected:text-code-fg"
                    onClick={() => setPicked(i)}
                  >
                    {t}
                  </button>
                ))}
              </div>
            )
          : <div className="flex min-w-0"><span className="inline-flex h-control-sm min-w-0 items-center bg-code-raised px-2.5 text-meta leading-5 font-medium text-code-fg [overflow-wrap:anywhere]">{tabs[0]}</span></div>}
        <CodeCopy text={shown} onCopied={onCopied} />
      </div>
      <pre
        tabIndex={0}
        aria-label={`${tabs[samples ? picked : 0] ?? 'code'}, code`}
        className="fade-x m-0 overflow-x-auto px-4 py-3 type-code-sm leading-5 whitespace-pre focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-surface-accent"
      >{shown}</pre>
    </div>
  )
}

export default CodeBlock

'use client'
import { Check, Copy } from 'lucide-react'
import { useCopy } from '@/react/hooks/useCopy'

// The code window's Copy (the console's CodeCopy.vue): on the dark bar, the icon and the word swap in one cell, so
// nothing moves. Used by CodeBlock; `light` is its form on the paper install line.
export interface CodeCopyProps {
  text: string
  light?: boolean
  onCopied?: () => void
}

export function CodeCopy({ text, light, onCopied }: CodeCopyProps) {
  const { copied, copy } = useCopy()
  async function run(t: string) {
    if (await copy(t)) onCopied?.()
  }
  return (
    <>
      <style href="ds-code-copy" precedence="ds">{css}</style>
      <button data-ds="code-copy" type="button" className="ds-codecopy" data-light={light || undefined} onClick={() => run(text)}>
        <span className="ds-codecopy-icon" aria-hidden="true"><Copy data-on={!copied || undefined} size={12} strokeWidth={1.5} /><Check data-on={copied || undefined} size={12} strokeWidth={2} /></span>
        <span className="ds-codecopy-word"><span data-on={!copied || undefined} aria-hidden={copied}>Copy</span><span data-on={copied || undefined} aria-hidden={!copied}>Copied</span></span>
        <span className="sr-only" aria-live="polite">{copied ? 'copied' : ''}</span>
      </button>
    </>
  )
}

export default CodeCopy

const css = `
.ds-codecopy { display: inline-flex; height: var(--ds-size-control-sm); flex-shrink: 0; align-items: center; gap: var(--ds-space-sm); padding: 0 10px; border: var(--ds-border-hairline) solid var(--ds-color-code-edge); background: var(--ds-color-code); color: var(--ds-color-code-fg); font-size: var(--ds-text-meta); font-weight: var(--ds-font-weight-medium); line-height: 20px; cursor: pointer; transition: border-color var(--ds-duration-micro) ease; }
.ds-codecopy:active { background: var(--ds-color-code-raised); }
@media (hover: hover) and (pointer: fine) { .ds-codecopy:hover { border-color: var(--ds-color-off-white); } }
.ds-codecopy:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-surface-accent); outline-offset: -2px; }
.ds-codecopy[data-light] { border-color: var(--ds-color-edge-strong); background: var(--ds-color-surface); color: var(--ds-color-fg); }
.ds-codecopy[data-light]:active { background: var(--ds-color-surface-subtle); }
@media (hover: hover) and (pointer: fine) { .ds-codecopy[data-light]:hover { border-color: var(--ds-color-action-secondary-edge-hover); } }
.ds-codecopy-icon, .ds-codecopy-word { display: inline-grid; }
.ds-codecopy-icon > *, .ds-codecopy-word > * { grid-area: 1 / 1; transition: opacity var(--ds-duration-swap) ease-in-out, filter var(--ds-duration-swap) ease-in-out, transform var(--ds-duration-swap) ease-in-out; }
.ds-codecopy-icon > :not([data-on]) { opacity: 0; filter: blur(4px); transform: scale(0.25); }
.ds-codecopy-word > :not([data-on]) { opacity: 0; filter: blur(2px); }
.ds-codecopy-word > :first-child:not([data-on]) { transform: translateY(-4px); }
.ds-codecopy-word > :last-child:not([data-on]) { transform: translateY(4px); }
@media (prefers-reduced-motion: reduce) {
  .ds-codecopy-icon > *, .ds-codecopy-word > * { filter: none; transform: none; transition: opacity var(--ds-duration-micro) ease; }
}
`

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

'use client'
import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * A copy button's state: copy(text) writes the clipboard, and copied is true for 1.5s after. Where the Clipboard API is
 * refused (a browser or a frame that denies it), the older copy command still works inside the click. Only if both are
 * refused does it answer false, and the text stays selectable.
 */
export function useCopy(ms = 1500) {
  const [copied, setCopied] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])
  const copy = useCallback(async (text: string): Promise<boolean> => {
    try {
      await navigator.clipboard.writeText(text)
    }
    catch {
      if (!copyByCommand(text)) return false
    }
    setCopied(true)
    clearTimeout(timer.current)
    // ds-latency: the Copied label stays 1.5s after the copy, which has already happened.
    timer.current = setTimeout(() => setCopied(false), ms)
    return true
  }, [ms])
  return { copied, copy }
}

// The older way: select the text in an unseen field, run the copy command, hand focus back.
function copyByCommand(text: string) {
  const back = document.activeElement as HTMLElement | null
  const field = document.createElement('textarea')
  field.value = text
  field.setAttribute('readonly', '')
  field.style.position = 'fixed'
  field.style.opacity = '0'
  document.body.appendChild(field)
  field.select()
  let ok = false
  try { ok = document.execCommand('copy') }
  catch { ok = false }
  field.remove()
  back?.focus()
  return ok
}

